window.DEX_DATA["sources:backport-c1595cf2ca0ccb63"]={"json":{"skins":[{"filename":"blackbelt.png"}],"names":[{"name":"布鲁斯"},{"name":"杰基"},{"name":"杰特"},{"name":"让·克洛德"},{"name":"史蒂文"}],"chat":[{"lines":[{"text":"就算已经是黑带，我也得继续训练！"},{"text":"快给我找些木板、砖块，还有瀑布！"}]},{"lines":[{"text":"喝！哈！呜——啊！"},{"text":"怎么样，震撼到了吗？有没有心生敬畏？"}]},{"lines":[{"text":"以我的功夫，什么都能当武器。"},{"text":"只用一根小指，我就能挡住一群发狂的拉达。"}]},{"lines":[{"text":"我是被豪力养大的。"},{"text":"要是养我的是怪力，说不定我还能更强。"}]}]}};
